ErrorOr<std::unique_ptr<SampleProfileReader>> SampleProfileReader::create(const std::string Filename, LLVMContext &C, vfs::FileSystem &FS, FSDiscriminatorPass P, const std::string RemapFilename) {
  // Create a unique_ptr to hold the SampleProfileReader instance
  std::unique_ptr<SampleProfileReader> Reader(new SampleProfileReader(C, FS, P));

  // Open the file and check for errors
  std::ifstream File(Filename, std::ios::in | std::ios::binary);
  if (!File.is_open()) {
    return ErrorOr<std::unique_ptr<SampleProfileReader>>(Error::FileNotFound);
  }

  // Read the file format and check for errors
  FileFormat Format;
  if (!Reader->readFileFormat(File, Format)) {
    return ErrorOr<std::unique_ptr<SampleProfileReader>>(Error::InvalidFileFormat);
  }

  // Create a remapper if RemapFilename is not empty
  if (!RemapFilename.empty()) {
    std::unique_ptr<SampleProfileRemapper> Remapper(new SampleProfileRemapper(C, FS, P));
    if (!Remapper->readFile(RemapFilename)) {
      return ErrorOr<std::unique_ptr<SampleProfileReader>>(Error::InvalidRemapFile);
    }
    Reader->setRemapper(std::move(Remapper));
  }

  // Return the SampleProfileReader instance
  return ErrorOr<std::unique_ptr<SampleProfileReader>>(std::move(Reader));
}
