ErrorOr<std::unique_ptr<SampleProfileReader>> SampleProfileReader::create(const std::string Filename, LLVMContext &C, vfs::FileSystem &FS, FSDiscriminatorPass P, const std::string RemapFilename) {
  ErrorOr<std::unique_ptr<SampleProfileReader>> Result;

  // Determine the file format
  auto FileFormat = determineFileFormat(Filename);
  if (!FileFormat) {
    return Result.takeError();
  }

  // Create the appropriate sample profile reader
  switch (*FileFormat) {
    case FileFormat::Text:
      Result = createTextSampleProfileReader(Filename, C, FS, P, RemapFilename);
      break;
    case FileFormat::Binary:
      Result = createBinarySampleProfileReader(Filename, C, FS, P, RemapFilename);
      break;
    default:
      return Result.takeError();
  }

  // Create a remapper underlying if RemapFilename is not empty
  if (!RemapFilename.empty()) {
    Result->setRemapper(createRemapper(RemapFilename, C, FS, P));
  }

  return Result;
}
