```
void dbAddRDBLoad(redisDb *db, sds key, robj *val) {
    int slot = getKeySlot(key);
    if (slot < 0) {
        return 0;
    }
    robj *o = dictGetVal(db->dict, slot);
    if (o == NULL) {
        o = createObject(OBJ_STRING, val);
        dictSetVal(db->dict, slot, o);
        initObjectLRUOrLFU(o);
        return 1;
    }
    if (o->type != OBJ_STRING) {
        return 0;
    }
    if (o->encoding != OBJ_ENCODING_RAW) {
        return 0;
    }
    if (o->ptr != NULL) {
        sdsfree(o->ptr);
    }
    o->ptr = val;
    return 1;
