```
class ThreadPool {
public:
    ThreadPool(int numThreads);
    ~ThreadPool();

    void addTask(std::function<void()> task);
    void waitForAllTasks();

private:
    std::vector<std::thread> threads;
    std::mutex mutex;
    std::condition_variable cv;
    std::queue<std::function<void()>> tasks;
};

ThreadPool::ThreadPool(int numThreads) {
    for (int i = 0; i < numThreads; i++) {
        threads.emplace_back([this] {
            while (true) {
                std::function<void()> task;
                {
                    std::unique_lock<std::mutex> lock(mutex);
                    cv.wait(lock, [this] { return !tasks.empty(); });
                    task = std::move(tasks.front());
                    tasks.pop();
                }
                task();
            }
        });
    }
}

ThreadPool::~ThreadPool() {
    {
        std::unique_lock<std::mutex> lock(mutex);
        cv.notify_all();
    }
    for (auto& thread : threads) {
        thread.join();
    }
}

void ThreadPool::addTask(std::function<void()> task) {
    {
        std::unique_lock<std::mutex> lock(mutex);
        tasks.push(std::move(task));
    }
    cv.notify_one();
}

void ThreadPool::waitForAllTasks() {
    {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return tasks.empty(); });
    }
}
```
This is a basic implementation of a thread pool in C++. It uses a vector of threads to execute tasks, and a queue to store the tasks. The `addTask` function adds a task to the queue, and the `waitForAllTasks` function waits for all the tasks to complete. The destructor blocks until all the threads have completed their tasks.

