```
static int has_usable_cert(SSL_CONNECTION *s, const SIGALG_LOOKUP *sig, int idx)
{
    X509 *x;
    EVP_PKEY *pkey;
    int mdnid, pknid, supported;
    size_t i;
    const char *mdname = NULL;
    SSL_CTX *sctx = SSL_CONNECTION_GET_CTX(s);

    /* Check if the certificate is present and has a usable private key */
    if (!ssl_has_cert(s, idx))
        return 0;

    /* Get the certificate and private key */
    x = s->cert->pkeys[idx].x509;
    pkey = s->cert->pkeys[idx].privatekey;

    /* Check if the certificate is usable with the given signature scheme */
    if (sig->hash != NID_undef)
        mdname = OBJ_nid2sn(sig->hash);
    supported = EVP_PKEY_digestsign_supports_digest(pkey, sctx->libctx,
                                                    mdname,
                                                    sctx->propq);
    if (supported <= 0)
        return 0;

    /* Check if the certificate is usable with the TLS 1.3 signature_algorithms_cert extension */
    if (s->s3.tmp.peer_cert_sigalgs != NULL) {
