static unsigned long long cumulativeKeyCountRead(kvstore *kvs, int didx) {
    unsigned long long total_key_count = 0;

    if (didx < 0 || didx >= kvs->num_dicts) {
        return 0;
    }

    for (int i = 0; i <= didx; i++) {
        total_key_count += kvs->dicts[i]? dictSize(kvs->dicts[i]) : 0;
    }

    return total_key_count;
}
