Constant *llvm::ConstantFoldLoadFromUniformValue(Constant *C, Type *Ty) {
    // Check if the value is uniform
    if (!C->isUniform()) {
        return nullptr;
    }

    // Check if the value is all zero, all ones, all undef or all poison
    if (C->isAllZero() || C->isAllOnes() || C->isAllUndef() || C->isAllPoison()) {
        // Create a new constant with the same value in the new type
        Constant *NewC = Constant::get(Ty, C->getZExtValue());
        return NewC;
    }

    // The value is not uniform or the result cannot be represented
    return nullptr;
}
