```
void LegalizerHelper::LegalizeResult llvm::createLibcall(
    MachineIRBuilder &MIRBuilder,
    RTLIB::Libcall Libcall,
    const CallLowering::ArgInfo &Result,
    ArrayRef<CallLowering::ArgInfo> Args,
    LostDebugLocObserver &LocObserver,
    MachineInstr *MI)
{
    // Get the target lowering
    const TargetLowering *TargetLowering = getTargetLowering();
    if (!TargetLowering) {
        return;
    }

    // Get the selection DAG target info
    const SelectionDAGTargetInfo *SelectionDAGInfo = getSelectionDAGInfo();
    if (!SelectionDAGInfo) {
        return;
    }

    // Create the libcall
    MachineInstr *LibcallInstr = MIRBuilder.createLibcall(
        Libcall,
        Result,
        Args,
        LocObserver,
        MI);

    // Legalize the libcall
    LegalizerHelper::LegalizeResult LegalizeResult = LegalizerHelper::legalize(
        TargetLowering,
        SelectionDAGInfo,
        LibcallInstr);

    // Return the legalized libcall
    return LegalizeResult.LegalizedInstr;
}
```
