    listAddNodeTail(d->rehashing_list, d);

    /* Update the bucket count for the given dictionary in the DB */
    unsigned long long from_size, to_size;
    dictRehashingInfo(d, &from_size, &to_size);
    d->bucket_count = from_size + to_size;
}
