namespace llvm {

std::unique_ptr<MIRParser> createMIRParserFromFile(StringRef Filename, SMDiagnostic &Error, LLVMContext &Context, std::function<void(Function &)> ProcessIRFunction) {
  // Open the file and create a MIR parser
  std::ifstream File(Filename);
  if (!File.is_open()) {
    Error = SMDiagnostic(Filename, "Could not open file");
    return nullptr;
  }
  std::unique_ptr<MIRParser> Parser(new MIRParser(File, Context));

  // Parse the MIR file and initialize the machine functions
  if (Parser->parseMIRFile()) {
    Error = SMDiagnostic(Filename, "Could not parse MIR file");
    return nullptr;
  }

  // Run the ProcessIRFunction on every IR function or stub loaded from the MIR file
  for (auto &Function : Parser->getModule()->getFunctionList()) {
    ProcessIRFunction(Function);
  }

  return Parser;
}

} // namespace llvm
