class CodeGenRegister {
public:
    CodeGenRegister(int value) : value(value) {}
    int getValue() const { return value; }
private:
    int value;
};

class NativeRegisterUnit {
public:
    NativeRegisterUnit(CodeGenRegister *R0, CodeGenRegister *R1 = nullptr) {
        if (R1 != nullptr) {
            registers.push_back(R0);
            registers.push_back(R1);
        } else {
            registers.push_back(R0);
        }
    }

    CodeGenRegister *getRegister(int index) const {
        if (index < 0 || index >= registers.size()) {
            return nullptr;
        }
        return registers[index];
    }

private:
    std::vector<CodeGenRegister *> registers;
};

NativeRegisterUnit *newRegUnit(CodeGenRegister *R0, CodeGenRegister *R1 = nullptr) {
    return new NativeRegisterUnit(R0, R1);
}

