        byte = 0;
        for (j = 0; j < 8; j++) {
            byte |= (bs->data[i] & (1 << j)) >> j;
        }
        addr[i] = byte;
    }

    // Fill the remaining bytes with the fill value
    for (i = length; i < 8; i++) {
        addr[i] = fill;
    }

    return 0;
}

