static bool combine(const CodeGenSubRegIndex *Idx, SmallVectorImpl<CodeGenSubRegIndex *> &Vec) {
  const CompMap &Composed = Idx->getComposites();
  for (auto &Elem : Vec) {
    const CompMap &ElemComposed = Elem->getComposites();
    if (Composed.size() != ElemComposed.size()) {
      return false;
    }
    for (auto &Pair : Composed) {
      auto It = ElemComposed.find(Pair.first);
      if (It == ElemComposed.end()) {
        return false;
      }
      if (It->second != Pair.second) {
        return false;
      }
    }
  }
  Vec.push_back(Idx);
  return true;
}
```
