[TEST_SETUP]
# Test setup code
from __future__ import annotations
from typing import Any


# Quaternion class
class btQuaternion:
    def __init__(self, w: float, x: float, y: float, z: float) -> None:
        self.w: float = w
        self.x: float = x
        self.y: float = y
        self.z: float = z

    def __mul__(self, other: Any) -> btQuaternion:
        if isinstance(other, btQuaternion):
            return btQuaternion(self.w * other.w - self.x * other.x - self.y * other.y - self.z * other.z,
                                self.w * other.x + self.x * other.w + self.y * other.z - self.z * other.y,
                                self.w * other.y - self.x * other.z + self.y * other.w + self.z * other.x,
                                self.w * other.z + self.x * other.y - self.y * other.x + self.z * other.w)
        elif isinstance(other, float):
            return btQuaternion(self.w * other, self.x * other, self.y * other, self.z * other)
        else:
            raise TypeError(f"unsupported operand type(s) for *: '{type(self).__name__}' and '{type(other).__name__}'")

    def __rmul__(self, other: Any) -> btQuaternion:
        if isinstance(other, float):
            return btQuaternion(self.w * other, self.x * other, self.y * other, self.z * other)
        else:
            raise TypeError(f"unsupported operand type(s) for *: '{type(other).__name__}' and '{type(self).__name__}'")

    def __truediv__(self, other: Any) -> btQuaternion:
        if isinstance(other, float):
            return btQuaternion(self.w / other, self.x / other, self.y / other, self.z / other)
        else:
            raise TypeError(f"unsupported operand type(s) for /: '{type(self).__name__}' and '{type(other).__name__}'")

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, btQuaternion):
            return self.w == other.w and self.x == other.x and self.y == other.y and self.z == other.z
        else:
            return False

    def __ne__(self, other: Any) -> bool:
        if isinstance(other, btQuaternion):
            return self.w != other.w or self.x != other.x or self.y != other.y or self.z != other.z
        else:
            return True

    def __repr__(self) -> str:
        return f"btQuaternion({self.w}, {self.x}, {self.y}, {self.z})"


# Test code
def test_btQuaternion_operator_divide_equal() -> None:
    quat = btQuaternion(1.0, 2.0, 3.0, 4.0)
    result = quat /= 2.0
    assert result == quat
    assert result.w == 0.5
    assert result.x == 1.0
    assert result.y == 1.5
    assert result.z == 2.0


if __name__ == "__main__":
    test_btQuaternion_operator_divide_equal()
[/TEST_SETUP]

