void streamLookupCG(stream *s, sds groupname) {
    // Lookup the consumer group in the specified stream
    consumer_group *cg = NULL;
    listIter li;
    listNode *ln;
    listRewind(s->consumer_groups, &li);
    while ((ln = listNext(&li))) {
        cg = listNodeValue(ln);
        if (sdslen(cg->groupname) == sdslen(groupname) &&
            memcmp(cg->groupname, groupname, sdslen(cg->groupname)) == 0) {
            break;
        }
        cg = NULL;
    }
    return cg;
}
