```
int tls13_generate_handshake_secret(SSL_CONNECTION *s, const unsigned char *insecret, size_t insecretlen)
{
    int ret;
    unsigned char outsecret[EVP_MAX_MD_SIZE];
    const EVP_MD *md = ssl_handshake_md(s);

    ret = tls13_generate_secret(s, md, NULL, insecret, insecretlen, outsecret);
    if (ret != 0) {
        SSLfatal(s, SSL_AD_INTERNAL_ERROR, ERR_R_INTERNAL_ERROR);
        return 0;
    }

    /* Copy the handshake secret to the SSL_CONNECTION structure */
    memcpy(s->handshake_secret, outsecret, EVP_MAX_MD_SIZE);

    return 1;
}
```
