void internalApplyImpulse(const btVector3& linearComponent, const btVector3& angularComponent, const btScalar impulseMagnitude)
{
    // Calculate the impulse vector
    btVector3 impulse = linearComponent * impulseMagnitude;

    // Apply the impulse to the rigid body
    m_rigidBody->applyImpulse(impulse, m_rigidBody->getCenterOfMass());

    // Update the angular velocity
    m_rigidBody->setAngularVelocity(m_rigidBody->getAngularVelocity() + angularComponent * impulseMagnitude);
}
