void luaEngineCall(scriptRunCtx *run_ctx, void *engine_ctx, void *compiled_function, robj **keys, size_t nkeys, robj **args, size_t nargs) {
    // Declare variables
    int err;
    lua_State *lua;
    StkId t;

    // Initialize Lua state
    lua = luaL_newstate();
    luaL_openlibs(lua);

    // Set global variables
    lua_pushstring(lua, "KEYS");
    lua_pushvalue(lua, -1);
    lua_setglobal(lua, "KEYS");
    lua_pop(lua, 1);

    lua_pushstring(lua, "ARGV");
    lua_pushvalue(lua, -1);
    lua_setglobal(lua, "ARGV");
    lua_pop(lua, 1);

    // Push function onto stack
    lua_pushvalue(lua, compiled_function);

    // Push arguments onto stack
    for (size_t i = 0; i < nargs; i++) {
        lua_pushstring(lua, args[i]);
    }

    // Call function
    err = lua_pcall(lua, nargs, 1, 0);

    // Check for errors
    if (err) {
        fprintf(stderr, "Error running script: %s\n", lua_tostring(lua, -1));
        lua_pop(lua, 1);
        return;
    }

    // Get return value
    t = lua_gettop(lua);
    lua_pushvalue(lua, t);

    // Pop return value and close Lua state
    lua_pop(lua, 1);
    lua_close(lua);
}
