int anetKeepAlive(char *err, int fd, int interval)
{
    int optval = 1;
    int keepidle = interval;
    int keepintvl = interval;
    int keepcnt = 3;

    if (setsockopt(fd, SOL_SOCKET, SO_KEEPALIVE, &optval, sizeof(optval)) < 0) {
        anetSetError(err, "setsockopt(SO_KEEPALIVE) failed: %s", strerror(errno));
        return -1;
    }

    if (setsockopt(fd, IPPROTO_TCP, TCP_KEEPIDLE, &keepidle, sizeof(keepidle)) < 0) {
        anetSetError(err, "setsockopt(TCP_KEEPIDLE) failed: %s", strerror(errno));
        return -1;
    }

    if (setsockopt(fd, IPPROTO_TCP, TCP_KEEPINTVL, &keepintvl, sizeof(keepintvl)) < 0) {
        anetSetError(err, "setsockopt(TCP_KEEPINTVL) failed: %s", strerror(errno));
        return -1;
    }

    if (setsockopt(fd, IPPROTO_TCP, TCP_KEEPCNT, &keepcnt, sizeof(keepcnt)) < 0) {
        anetSetError(err, "setsockopt(TCP_KEEPCNT) failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}
```
This function enables the TCP keep-alive mechanism on the socket `fd` with the specified `interval`. The `interval` parameter is used to set the `TCP_KEEPIDLE`, `TCP_KEEPINTVL`, and `TCP_KEEPCNT` options. If any of the `setsockopt` calls fails, an error message is set in the `err` buffer and the function returns `-1`. Otherwise, the function returns `0`.

