#include <string.h>

typedef struct connection {
    int type;
    int socket;
    void *data;
} connection;

static connection *connCreateSocket(void) {
    connection *conn = malloc(sizeof(connection));
    if (conn == NULL) {
        fprintf(stderr, "Failed to allocate memory for connection\n");
        exit(1);
    }
    conn->type = 0;
    conn->socket = 0;
    conn->data = NULL;
    return conn;
}

static void connAccept(connection *conn) {
    if (conn->type == 0) {
        fprintf(stderr, "Connection type not set\n");
        exit(1);
    }
    if (conn->socket == 0) {
        fprintf(stderr, "Socket not set\n");
        exit(1);
    }
    // Accept the connection
    if (accept(conn->socket, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to accept connection\n");
        exit(1);
    }
}

static void connConnect(connection *conn) {
    if (conn->type == 0) {
        fprintf(stderr, "Connection type not set\n");
        exit(1);
    }
    if (conn->socket == 0) {
        fprintf(stderr, "Socket not set\n");
        exit(1);
    }
    // Connect the socket
    if (connect(conn->socket, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to connect socket\n");
        exit(1);
    }
}

int main(void) {
    connection *conn = connCreateSocket();
    conn->type = 1;
    conn->socket = 1234;
    connAccept(conn);
    connConnect(conn);
    return 0;
}
