btQuaternion getRotation(const btMatrix3x3& m) {
    btQuaternion q;
    btScalar trace = m[0][0] + m[1][1] + m[2][2];
    if (trace > 0) {
        btScalar s = btSqrt(trace + 1.0);
        q.set128(btSimdFloat4(m[2][1] - m[1][2], m[0][2] - m[2][0], m[1][0] - m[0][1], s * 0.5));
        q *= btScalar(0.5) / s;
    } else {
        int i = 0;
        if (m[1][1] > m[0][0]) i = 1;
        if (m[2][2] > m[i][i]) i = 2;
        int j = (i + 1) % 3;
        int k = (i + 2) % 3;
        btScalar s = btSqrt(m[i][i] - m[j][j] - m[k][k] + 1.0);
        q.set128(btSimdFloat4(m[k][j] - m[j][k], m[j][i] + m[i][j], m[k][i] + m[i][k], s * 0.5));
        q *= btScalar(0.5) / s;
    }
    return q;
}
```
