bool SCEVExpander::isExpandedAddRecExprPHI(PHINode *PN, Instruction *IncV, const Loop *L) {
  // Check if the phi is in a form that would have been generated by LSR.
  if (PN->getNumOperands() != 2 || PN->getOperand(0) != PN->getOperand(1))
