std::pair<Value *, FPClassTest> fcmpToClassTest(FCmpInst::Predicate Pred, const Function &F, Value *LHS, Value *RHS, bool LookThroughSrc) {
  // Compute the mask for the fcmp instruction
  unsigned Mask = 0;
  switch (Pred) {
  case FCmpInst::Predicate::EQ:
    Mask = FPClassTest::EQ;
    break;
  case FCmpInst::Predicate::NE:
    Mask = FPClassTest::NE;
    break;
  case FCmpInst::Predicate::LT:
    Mask = FPClassTest::LT;
    break;
  case FCmpInst::Predicate::LE:
    Mask = FPClassTest::LE;
    break;
  case FCmpInst::Predicate::GT:
    Mask = FPClassTest::GT;
    break;
  case FCmpInst::Predicate::GE:
    Mask = FPClassTest::GE;
    break;
  default:
    llvm_unreachable("Invalid fcmp predicate");
  }

  // Compute the result of the fcmp instruction
  Value *Result = nullptr;
  if (LookThroughSrc) {
    Result = F.getOrCreateResult(LHS, RHS, Mask);
  } else {
    Result = F.getOrCreateResult(LHS, RHS, Mask, false);
  }

  // Return the result as a pair of values
  return std::make_pair(LHS, Result);
}

} // namespace llvm
```
