std::pair<Value *, FPClassTest> llvm::fcmpToClassTest(FCmpInst::Predicate Pred, const Function &F, Value *LHS, Value *RHS, bool LookThroughSrc) {
  // Get the mask for the given predicate
  unsigned Mask = FCmpInst::getMask(Pred);

  // Get the operands for the fcmp instruction
  Value *Op1 = LHS;
  Value *Op2 = RHS;

  // If LookThroughSrc is true, consider the input value when computing the mask
  if (LookThroughSrc) {
    // Get the input value for the fcmp instruction
    Value *Input = F.getArg(0);

    // If the input value is a constant, use it as the first operand
    if (isa<Constant>(Input)) {
      Op1 = Input;
    }
  }

  // Create a new pair of values
  std::pair<Value *, FPClassTest> Pair;

  // Set the first element of the pair to the first operand
  Pair.first = Op1;

  // Set the second element of the pair to the second operand
  Pair.second = Op2;

  // Return the pair
  return Pair;
}
```
