#include <openssl/quic.h>

int ossl_quic_txfc_init(QUIC_TXFC *txfc, QUIC_TXFC *conn_txfc) {
    if (txfc == NULL) {
        return -1;
    }

    if (conn_txfc != NULL) {
        txfc->conn_txfc = conn_txfc;
        txfc->conn_txfc->ref_count++;
    }

    txfc->ref_count = 1;
    txfc->max_stream_data = 0;
    txfc->max_data = 0;
    txfc->send_window = 0;
    txfc->recv_window = 0;
    txfc->stream_data = 0;
    txfc->data = 0;

    return 0;
}
```
