void grow(size_t N) {
  // Check if the buffer is already large enough
  if (N <= buffer.size()) {
    return;
  }

  // Calculate the new size of the buffer
  size_t newSize = buffer.size() + N;

  // Allocate a new buffer with the new size
  char* newBuffer = new char[newSize];

  // Copy the contents of the old buffer to the new buffer
  memcpy(newBuffer, buffer, buffer.size());

  // Free the old buffer
  delete[] buffer;

  // Set the new buffer as the current buffer
  buffer = newBuffer;
}
```
