void grow(size_t N) {
    if (N > capacity) {
        size_t new_capacity = capacity * 2;
        while (new_capacity < N) {
            new_capacity *= 2;
        }
        T* new_buffer = new T[new_capacity];
        for (size_t i = 0; i < size; i++) {
            new_buffer[i] = buffer[i];
        }
        delete[] buffer;
        buffer = new_buffer;
        capacity = new_capacity;
    }
}
