const CodeGenIntrinsic *TreePatternNode::getIntrinsicInfo(const CodeGenDAGPatterns &CDP) const {
  if (isLeaf()) {
    return nullptr;
  }

  Record *op = getOperator();
  if (op == nullptr) {
    return nullptr;
  }

  unsigned IID = op->getIntrinsicID();
  if (IID == 0) {
    return nullptr;
  }

  return &CDP.getIntrinsicInfo(IID - 1);
}
