void ossl_quic_txpim_free(QUIC_TXPIM *txpim) {
    QUIC_TXPIM_PKT_EX *n, *nnext;

    for (n = txpim->head; n != NULL; n = nnext) {
        nnext = n->next;

        ossl_quic_txpim_pkt_release(n);
    }

    free_list(txpim->head);
    free_list(txpim->tail);

    OPENSSL_free(txpim);
}
