void printBitVectorAsHex(raw_ostream &OS, const BitVector &Bits, unsigned Width) {
  // Print the BitVector as a sequence of hex numbers using a little-endian mapping.
  // Width is the number of bits per hex number.

  // Iterate over the BitVector and print each bit as a hex number.
  for (size_t i = 0; i < Bits.size(); i++) {
    // Get the current bit.
    bool bit = Bits.test(i);

    // Print the bit as a hex number.
    OS << (bit ? "1" : "0");

    // If we have reached the end of the current hex number, print a space.
    if (i % Width == Width - 1) {
      OS << " ";
    }
  }
}
```
