int reclaimFilePageCache(int fd, size_t offset, size_t length) {
    // Get the file descriptor for the file
    int file_fd = open(fd, O_RDONLY);
    if (file_fd == -1) {
        perror("open");
        return -1;
    }

    // Get the file size
    off_t file_size = lseek(file_fd, 0, SEEK_END);
    if (file_size == -1) {
        perror("lseek");
        close(file_fd);
        return -1;
    }

    // Calculate the offset and length of the pages to be reclaimed
    size_t page_offset = offset / getpagesize();
    size_t page_length = length / getpagesize();

    // Reclaim the pages
    int ret = madvise(file_fd, page_offset, page_length, MADV_DONTNEED);
    if (ret == -1) {
        perror("madvise");
        close(file_fd);
        return -1;
    }

    // Close the file descriptor
    close(file_fd);

    return 0;
}
```
