void OrcX86_64_Base::writeTrampolines(char *TrampolineBlockWorkingMem, ExecutorAddr TrampolineBlockTargetAddress, ExecutorAddr ResolverAddr, unsigned NumTrampolines) {
  // Calculate the address of the first trampoline
  char *TrampolineAddress = TrampolineBlockWorkingMem + sizeof(void *);

  // Write the trampolines into the memory
  for (unsigned i = 0; i < NumTrampolines; i++) {
    // Calculate the address of the current trampoline
    char *CurrentTrampolineAddress = TrampolineAddress + (i * sizeof(void *));

    // Write the trampoline into the memory
    *(void **)CurrentTrampolineAddress = TrampolineBlockTargetAddress;
  }

  // Write the resolver address into the memory
  *(void **)(TrampolineBlockWorkingMem) = ResolverAddr;
}
