void updateCommandLatencyHistogram(struct hdr_histogram **latency_histogram, int64_t duration_hist) {
    int64_t duration = duration_hist / 1000; // Convert to microseconds
    int64_t counts = (*latency_histogram)->counts;
    int64_t total_counts = 0;

    for (int i = 0; i < counts; i++) {
        if (duration >= (*latency_histogram)->bucket_config.lowest_discernible_value && duration <= (*latency_histogram)->bucket_config.highest_trackable_value) {
            (*latency_histogram)->counts[i]++;
            total_counts++;
        }
    }

    if (total_counts == 0) {
        // Allocate memory for the histogram if needed
        if (!(*latency_histogram)->counts) {
            int r = hdr_init((*latency_histogram)->bucket_config.lowest_discernible_value, (*latency_histogram)->bucket_config.highest_trackable_value, (*latency_histogram)->bucket_config.significant_figures, latency_histogram);
            if (r) {
                return r;
            }
        }

        // Trim the duration to the upper/lower tracking limits
        if (duration < (*latency_histogram)->bucket_config.lowest_discernible_value) {
            duration = (*latency_histogram)->bucket_config.lowest_discernible_value;
        } else if (duration > (*latency_histogram)->bucket_config.highest_trackable_value) {
            duration = (*latency_histogram)->bucket_config.highest_trackable_value;
        }

        // Update the histogram with the trimmed duration
        (*latency_histogram)->counts[duration]++;
    }
}
```

