class SampleProfileReaderBinary {
public:
    ErrorOr<StringRef> readString() {
        // Read the string length
        uint32_t length = 0;
        if (auto error = readUInt32(&length)) {
            return error;
        }

        // Read the string data
        std::string data;
        data.resize(length);
        if (auto error = readBytes(&data[0], length)) {
            return error;
        }

        // Decode the string
        std::string decoded;
        if (auto error = decodeString(data, &decoded)) {
            return error;
        }

        return decoded;
    }

private:
    ErrorOr<uint32_t> readUInt32(uint32_t* value) {
        // Read the value from the profile
        if (auto error = readBytes(value, sizeof(uint32_t))) {
            return error;
        }

        // Convert the value to host byte order
        *value = ntohl(*value);

        return ErrorOr<uint32_t>(*value);
    }

    ErrorOr<std::string> readBytes(char* data, size_t length) {
        // Read the data from the profile
        if (auto error = readBytes(data, length)) {
            return error;
        }

        // Convert the data to a string
        std::string str(data, length);

        return ErrorOr<std::string>(str);
    }

    ErrorOr<std::string> decodeString(const std::string& data, std::string* decoded) {
        // Decode the string
        if (auto error = decodeString(data, decoded)) {
            return error;
        }

