        // Check if the server supports compression
        if (sc->server_compression_supported) {
            // Check if the client has a preferred compression algorithm
            if (sc->client_preferred_compression_algorithm != TLSEXT_comp_cert_none) {
                // Use the client's preferred compression algorithm
                return sc->client_preferred_compression_algorithm;
            } else {
