int check_suffix(const char *str, const char *suffix) {
    int i, j;
    for (i = 0; str[i] != '\0'; i++) {
        if (str[i] == ' ') {
            for (j = 0; suffix[j] != '\0'; j++) {
                if (str[i + j] != suffix[j]) {
                    break;
                }
            }
            if (j == strlen(suffix)) {
                return i;
            }
        }
    }
    return -1;
}
```
