static int check_suffix(const char *str, const char *suffix) {
    size_t str_len = strlen(str);
    size_t suffix_len = strlen(suffix);

    if (str_len < suffix_len) {
        return -1;
    }

    const char *last_space = strrchr(str, ' ');
    if (last_space == NULL) {
        return -1;
    }

    const char *suffix_start = last_space + 1;
    if (strncmp(suffix_start, suffix, suffix_len) == 0) {
        return last_space - str;
