void setEulerZYX(const b3Scalar& yawZ, const b3Scalar& pitchY, const b3Scalar& rollX)
{
    // Convert Euler angles to quaternion
    b3Quaternion q;
    q.setValue(b3Cos(yawZ / 2), b3Sin(yawZ / 2), b3Cos(pitchY / 2), b3Sin(pitchY / 2));
    q.normalize();

