void setRotation(const btQuaternion& q) {
    // Calculate the length of the quaternion
    btScalar length = q.length2();

    // Normalize the quaternion
    btQuaternion normalizedQ = q / length;

    // Calculate the matrix from the normalized quaternion
    btMatrix3x3 matrix;
    matrix.setValue(
        1 - 2 * normalizedQ.y() * normalizedQ.y() - 2 * normalizedQ.z() * normalizedQ.z(),
        2 * normalizedQ.x() * normalizedQ.y() - 2 * normalizedQ.z() * normalizedQ.w(),
        2 * normalizedQ.x() * normalizedQ.z() + 2 * normalizedQ.y() * normalizedQ.w(),

        2 * normalizedQ.x() * normalizedQ.y() + 2 * normalizedQ.z() * normalizedQ.w(),
        1 - 2 * normalizedQ.x() * normalizedQ.x() - 2 * normalizedQ.z() * normalizedQ.z(),
        2 * normalizedQ.y() * normalizedQ.z() - 2 * normalizedQ.x() * normalizedQ.w(),

        2 * normalizedQ.x() * normalizedQ.z() - 2 * normalizedQ.y() * normalizedQ.w(),
        2 * normalizedQ.y() * normalizedQ.z() + 2 * normalizedQ.x() * normalizedQ.w(),
        1 - 2 * normalizedQ.x() * normalizedQ.x() - 2 * normalizedQ.y() * normalizedQ.y()
    );

    // Set the matrix
    setValue(matrix);
}
```
