```
static void processDbgDeclares(FunctionLoweringInfo &FuncInfo) {
    // Get the llvm.dbg.declare instructions
    auto &DbgDeclares = FuncInfo.getDbgDeclares();

    // Iterate over the llvm.dbg.declare instructions
    for (auto &DbgDeclare : DbgDeclares) {
        // Get the variable being declared
        auto *Var = DbgDeclare.getVariable();

        // Get the type of the variable
        auto *VarType = Var->getType();

        // Check if the variable is a pointer
        if (VarType->isPointerTy()) {
            // Get the pointee type
            auto *PointeeType = VarType->getPointeeType();

            // Check if the pointee type is a struct
            if (PointeeType->isStructTy()) {
                // Get the struct type
                auto *StructType = PointeeType->getStructType();

                // Check if the struct type has a name
                if (StructType->hasName()) {
                    // Get the name of the struct type
                    auto StructName = StructType->getName();

                    // Print the name of the struct type
                    std::cout << "Struct type: " << StructName << std::endl;
                }
            }
        }
    }
}
```
This function takes a `FunctionLoweringInfo` object as input and collects the `llvm.dbg.declare` instructions from the function. It then iterates over the `llvm.dbg.declare` instructions and checks if the variable being declared is a pointer to a struct. If it is, it gets the name of the struct type and prints it to the console.

column4:
```
void processDbgDeclares(FunctionLoweringInfo &FuncInfo) {
    // Get the llvm.dbg.declare instructions
    auto &DbgDeclares = FuncInfo.getDbgDeclares();

    // Iterate over the llvm.dbg.declare instructions
    for (auto &DbgDeclare : DbgDeclares) {
        // Get the variable being declared
        auto &Var = DbgDeclare.getVariable();

        // Get the type of the variable
        auto &Type = Var.getType();

        // Check if the type is a pointer
        if (Type.isPointerTy()) {
            // Get the pointee type
            auto &PointeeType = Type.getPointeeType();

            // Check if the pointee type is a struct
            if (PointeeType.isStructTy()) {
                // Get the struct type
                auto &StructType = PointeeType.getStructType();

                // Check if the struct type has a name
                if (StructType.hasName()) {
                    // Get the name of the struct type
                    auto &StructName = StructType.getName();

                    // Print the name of the struct type
                    std::cout << "Struct type: " << StructName << std::endl;
                }
            }
        }
    }
