void AMDGPUInstructionSelector::splitIllegalMUBUFOffset(MachineIRBuilder &B, Register &SOffset, int64_t &ImmOffset) const {
  // Check if the immediate offset fits in the immediate field
  if (isLegalMUBUFImmOffset(ImmOffset)) {
    // Immediate offset fits in the immediate field, no need to split
    return;
  }

  // Immediate offset does not fit in the immediate field, split it
  // into a variable component and a constant component
  int64_t ImmOffsetConst = ImmOffset & 0xFF;
  int64_t ImmOffsetVar = ImmOffset - ImmOffsetConst;

  // Set the variable component to the register
  SOffset = B.getInt64Ty(ImmOffsetVar);

  // Set the constant component to the immediate field
  ImmOffset = ImmOffsetConst;
}
```
